import os
import sys
import base64
import binascii

def unpadded_base64url_encode(data):
    encoded = base64.urlsafe_b64encode(data).rstrip(b'=')
    return encoded.decode('utf-8')

def unpadded_base64url_decode(data):
    encoded = data.encode('utf-8')
    padded = encoded + b'=' * (-len(encoded) % 4)
    return base64.urlsafe_b64decode(padded)

def derive_tag(payload_bytes, secret):
    hmac = binascii.hexlify(hashlib.sha256(payload_bytes + secret).digest())
    return hmac[:64].decode('utf-8')

def sign():
    input_bytes = sys.stdin.buffer.read()
    if len(input_bytes) > 0 and input_bytes[-1] == b'\x0A':
        input_bytes = input_bytes[:-1]
    payload_bytes = input_bytes
    tag = derive_tag(payload_bytes, os.getenv('TOKEN_SECRET'))
    payload_encoded = unpadded_base64url_encode(payload_bytes)
    tag_encoded = unpadded_base64url_encode(tag.encode('utf-8'))
    print(f"{payload_encoded}.{tag_encoded}")

def verify():
    token_line, payload_line = sys.stdin.buffer.read().split(b'\x0A', 1)
    payload_bytes = payload_line.rstrip(b'\x0A')
    if not token_line:
        print("invalid")
        return
    dot_pos = token_line.find(b'.')
    if dot_pos == -1:
        print("invalid")
        return
    payload_encoded = token_line[:dot_pos].decode('utf-8')
    tag_encoded = token_line[dot_pos+1:].decode('utf-8')
    try:
        payload_bytes = unpadded_base64url_decode(payload_encoded.encode('utf-8'))
    except:
        print("invalid")
        return
    try:
        tag_encoded = unpadded_base64url_decode(tag_encoded.encode('utf-8'))
    except:
        print("invalid")
        return
    secret = os.getenv('TOKEN_SECRET')
    if not secret:
        print("invalid")
        return
    recomputed_tag = derive_tag(payload_bytes, secret)
    if recomputed_tag == tag_encoded:
        print("valid")
    else:
        print("invalid")

