import sys
import os
import base64
from typing import Optional

def sign(input_bytes: bytes) -> str:
    if input_bytes.endswith(b'\n'):
        input_bytes = input_bytes[:-1]
    payload_b64url = base64.urlsafe_b64encode(input_bytes).rstrip(b'=')
    tag = compute_tag(input_bytes)
    tag_b64url = base64.urlsafe_b64encode(tag).rstrip(b'=')
    return f"{payload_b64url}.{tag_b64url}"

def compute_tag(input_bytes: bytes) -> bytes:
    secret = os.getenv('TOKEN_SECRET')
    if not secret:
        raise ValueError("TOKEN_SECRET environment variable not set")
    combined = input_bytes + secret.encode()
    return hashlib.sha256(combined).digest()[:32]

def verify(token: str, payload: bytes) -> str:
    if not token:
        return "invalid"
    dot_pos = token.find('.')
    if dot_pos == -1:
        return "invalid"
    payload_b64url = token[:dot_pos]
    tag_b64url = token[dot_pos + 1:]
    try:
        payload_bytes = base64.urlsafe_b64decode(payload_b64url + '=' * (-len(payload_b64url) % 4))
    except:
        return "invalid"
    if payload.endswith(b'\n'):
        payload_bytes = payload_bytes[:-1]
    computed_tag = compute_tag(payload_bytes)
    try:
        tag_bytes = base64.urlsafe_b64decode(tag_b64url + '=' * (-len(tag_b64url) % 4))
    except:
        return "invalid"
    if computed_tag == tag_bytes:
        return "valid"
    else:
        return "invalid"

def main():
    if len(sys.argv) != 2:
        sys.exit(1)
    action = sys.argv[1]
    if action == 'sign':
        input_bytes = sys.stdin.buffer.read()
        result = sign(input_bytes)
        sys.stdout.buffer.write(result.encode())
    elif action == 'verify':
        token_line, payload_line = sys.stdin.buffer.read().splitlines()
        payload = payload_line.encode()
        result = verify(token_line.decode(), payload)
        sys.stdout.buffer.write(result.encode())
    else:
        sys.exit(1)

if __name__ == "__main__":
    import hashlib
    main()
